import{_ as e,o as r,c as a,ag as d}from"./chunks/framework.DzGOF12C.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"computer/Web-Development/Web-Frontend/00-Overview-Frontend-Stack.md","filePath":"computer/Web-Development/Web-Frontend/00-Overview-Frontend-Stack.md"}'),o={name:"computer/Web-Development/Web-Frontend/00-Overview-Frontend-Stack.md"};function n(i,t,s,l,u,h){return r(),a("div",null,[...t[0]||(t[0]=[d('<h2 id="전체-그림-웹은-왜-이렇게-여러-겹으로-쌓여있나" tabindex="-1">전체 그림: 웹은 왜 이렇게 여러 겹으로 쌓여있나 <a class="header-anchor" href="#전체-그림-웹은-왜-이렇게-여러-겹으로-쌓여있나" aria-label="Permalink to &quot;전체 그림: 웹은 왜 이렇게 여러 겹으로 쌓여있나&quot;">​</a></h2><p>웹 프론트엔드 기술은 &quot;필요에 따라 그 아래 것을 재료로 삼아 새로운 도구를 얹는&quot; 방식으로 계속 층이 쌓여왔다. TIL 사이트(VitePress)를 예로 들면 이렇게 4단계다.</p><table tabindex="0"><thead><tr><th>층</th><th>이름</th><th>역할</th><th>이 자체로 실행 가능한가?</th></tr></thead><tbody><tr><td>1</td><td><strong>JavaScript</strong></td><td>웹의 유일한 프로그래밍 언어(로직/동작)</td><td>✅ 브라우저가 직접 실행</td></tr><tr><td>2</td><td><strong>Vue</strong></td><td>JS로 화면을 컴포넌트 단위로 만드는 UI 프레임워크</td><td>❌ 빌드해야 실행 가능</td></tr><tr><td>3</td><td><strong>Vite</strong></td><td>Vue 코드를 브라우저가 이해할 형태로 변환/번들링하는 빌드 도구</td><td>(도구 자체는 Node.js에서 실행)</td></tr><tr><td>4</td><td><strong>VitePress</strong></td><td>Vite+Vue를 재료로 &quot;마크다운 → 문서 사이트&quot; 용도에 특화시킨 정적 사이트 생성기</td><td>(내부적으로 1~3 전부 사용)</td></tr></tbody></table><h2 id="언어-3형제와-프로그래밍-언어의-차이" tabindex="-1">언어 3형제와 프로그래밍 언어의 차이 <a class="header-anchor" href="#언어-3형제와-프로그래밍-언어의-차이" aria-label="Permalink to &quot;언어 3형제와 프로그래밍 언어의 차이&quot;">​</a></h2><p>HTML(구조)·CSS(스타일)는 마크업/스타일 언어일 뿐 로직이 없고, <strong>JavaScript만이 Java·Python과 동급인 진짜 프로그래밍 언어</strong>다(변수, 함수, 조건문, 반복문을 갖춤). &quot;버튼이 어떻게 생겼는지&quot;는 HTML/CSS가, &quot;버튼을 클릭하면 무슨 일이 일어나는지&quot;는 JS가 담당한다.</p><h2 id="같은-급-프레임워크들" tabindex="-1">같은 급 프레임워크들 <a class="header-anchor" href="#같은-급-프레임워크들" aria-label="Permalink to &quot;같은 급 프레임워크들&quot;">​</a></h2><p>Vue와 같은 레벨(JS 기반 UI 프레임워크)에 있는 경쟁자들:</p><table tabindex="0"><thead><tr><th>프레임워크</th><th>만든 곳</th><th>위에 얹힌 메타 프레임워크</th></tr></thead><tbody><tr><td>React</td><td>Meta</td><td>Next.js, Docusaurus</td></tr><tr><td>Vue</td><td>Evan You(개인)</td><td>Nuxt, <strong>VitePress</strong></td></tr><tr><td>Angular</td><td>Google</td><td>(자체 완결형이라 메타프레임워크 개념이 약함)</td></tr><tr><td>Svelte</td><td>Rich Harris(개인)</td><td>SvelteKit</td></tr></tbody></table><p>TypeScript도 같은 &quot;레이어를 쌓는&quot; 패턴이지만 대상이 다르다 — TypeScript는 <strong>JS 언어 자체</strong>에 타입 체크를 더하는 것이고, VitePress는 <strong>Vue라는 프레임워크</strong>를 문서 사이트라는 특정 용도에 특화시킨 것이다.</p><h2 id="자세한-내용" tabindex="-1">자세한 내용 <a class="header-anchor" href="#자세한-내용" aria-label="Permalink to &quot;자세한 내용&quot;">​</a></h2><ul><li>[[01-JavaScript-Language-Basics|01. JavaScript 언어 기초]]</li><li>[[02-Vue-Framework|02. Vue 프레임워크 내부 동작]]</li><li>[[03-Vite-Build-Tool|03. Vite 빌드 도구 내부 동작]]</li><li>[[04-VitePress-Static-Site-Generator|04. VitePress 파이프라인]]</li></ul>',11)])])}const S=e(o,[["render",n]]);export{p as __pageData,S as default};
